mutations.before:
pure def matchingVersions(env: Environment, premise: Premise): List[VersionPin] =
  env.currentVersions.select(pin => and {
    pin.profile == premise.request.record.scope.profile,
    pin.interpretationId == premise.request.record.provenance.interpretationId,
  })

mutations.after:
pure def matchingVersions(env: Environment, premise: Premise): List[VersionPin] = {
  val pins = env.currentVersions.select(pin => and {
    pin.profile == premise.request.record.scope.profile,
    pin.interpretationId == premise.request.record.provenance.interpretationId,
  })
  if (pins.length() == 0) List() else List(pins.head())
}

pure def matchingEvidence(env: Environment, premise: Premise): List[EvidenceDecision] = {
  val decisions = env.evidence.select(decision => decision.premise.request.entryId == premise.request.entryId)
  if (decisions.length() == 0) List() else List(decisions.head())
}

| Rejected(reason) => match J::decodeRecord(premise.request.record) {
        | BadRecord => blocked(provenance, List(RegistryRejected(reason)))
        | RecordValue(record) => { conclusion: knownOf(premise.questionId, record), issues: List(), provenance: provenance }
      }
